'use strict';
/**
 * The DORMANCY SUPERVISOR's tick, generated by running the LIVE block out of
 * `src/index.js`.
 *
 * ---- WHAT IS SLICED, AND WHY THAT IS NOT "STUBBING A REWRITE" -------------
 *
 * The whole `// ── Collector dormancy ──` region is lifted CONTIGUOUSLY, from
 * `_DORMANCY_TICK_MS` through `_wakeForFocus`, and evaluated in a `vm` with its
 * five free names supplied: `_COLLECTOR_DEFS`, `createDormancyState`,
 * `payloadEmpty`, `io` and `console`.
 *
 * This repo records a real trap about stubbing — "stubbing means writing glue and
 * then comparing MY GLUE against the port" (page-gate-audit, on the Connections
 * page). It does not apply here, and the difference is worth stating: the four
 * things supplied are DATA AND SPIES, not logic.
 *
 *   _COLLECTOR_DEFS      the real registry, required from src/collection.js
 *   createDormancyState  the real state machine, required from collectors/util.js
 *   payloadEmpty         the real predicate, required from collectors/util.js
 *   io                   a room-size lookup and an emit RECORDER
 *   session/collectors   objects holding a lastPayload and recording which of
 *                        suspend/resume/probe/refreshNow was called
 *
 * Every decision under test — the eligibility filter, the enabled check, the
 * watching guard, the observe/probe ordering, and the rule that only a VERDICT
 * sets `changed` — runs as the original. Nothing here reimplements any of it.
 *
 * ---- SEQUENCES AGAIN ------------------------------------------------------
 *
 * The supervisor is stateful across ticks, so each case is an ordered list of
 * ticks with the payloads each collector had at that moment, recording the
 * operations performed and the `collection:status` payloads emitted.
 *
 *   MIKRODASH_SRC=../MikroDash node tools/dormancy-tick-cases.js
 *   MIKRODASH_SRC=../MikroDash node tools/dormancy-tick-cases.js --check
 */

const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const ROOT = path.join(__dirname, '..');
const LIVE = path.resolve(process.env.MIKRODASH_SRC || path.join(ROOT, '..', 'MikroDash'));
const OUT = path.join(ROOT, 'testdata', 'dormancy-tick-cases.json');

const { createDormancyState, payloadEmpty } = require(path.join(LIVE, 'src', 'collectors', 'util.js'));
const { COLLECTORS } = require(path.join(LIVE, 'src', 'collection.js'));

// ---- Slice the region ------------------------------------------------------
// Anchored on CONTENT. index.js is ~7,200 lines and everything above this moves.
const src = fs.readFileSync(path.join(LIVE, 'src', 'index.js'), 'utf8');
const lines = src.split('\n');
const start = lines.findIndex((l) => l.startsWith('const _DORMANCY_TICK_MS'));
if (start < 0) throw new Error('anchor lost: const _DORMANCY_TICK_MS');
const endMarker = lines.findIndex((l, i) => i > start && l.startsWith('function _idleSuspend'));
if (endMarker < 0) throw new Error('anchor lost: function _idleSuspend, which follows the region');
const slice = lines.slice(start, endMarker).join('\n');

// The region must still contain the functions this corpus drives. A slice that
// lost one would evaluate and then throw at call time, which is a worse failure
// than this.
for (const fn of ['_dormancyTick', '_resetDormancy', '_wakeForFocus', '_resumeCollector',
  '_probeCollector', '_emitDormancy']) {
  if (!slice.includes('function ' + fn)) throw new Error(`the slice lost ${fn}`);
}
// And it must still be the LOOP, not a reduced version of it.
if (!slice.includes('for (const def of _DORMANCY_DEFS)')) {
  throw new Error('the slice no longer walks _DORMANCY_DEFS — it is not the supervisor');
}

/** Build a world, run the ticks, record everything. */
function run(spec) {
  const ops = [];
  const emits = [];
  // THE CLOCK IS CONTROLLED INSIDE THE VM. `_dormancyTick` takes no `now` — it
  // reads `Date.now()` itself and passes the result to observe/dueForProbe. A
  // corpus on the real clock would differ on every run and `--check` would be
  // permanently stale, which is the trap routers-public-cases.js fell into.
  let clock = 0;
  const io = {
    sockets: { adapter: { rooms: { get: () => (spec.watching ? { size: 1 } : null) } } },
  };
  const mkColl = (key) => ({
    lastPayload: null,
    suspend() { ops.push({ tick: spec._t, key, op: 'suspend' }); },
    resume() { ops.push({ tick: spec._t, key, op: 'resume' }); },
    // NO `probe` and NO `refreshNow` on purpose for most collectors: the live
    // `_probeCollector` prefers probe(), falls back to resume()+refreshNow(), and
    // which fallback it takes is part of what the port must reproduce. One
    // collector below is given each shape.
  });
  const session = {
    routerId: 'r-under-test',
    _destroyed: false,
    ros: { routerLabel: 'lbl' },
    collection: { enabled: spec.enabled },
  };
  const collectors = {};
  for (const key of spec.keys) {
    collectors[key] = mkColl(key);
    if (spec.withProbe && spec.withProbe.includes(key)) {
      collectors[key].probe = () => ops.push({ tick: spec._t, key, op: 'probe' });
    }
    if (spec.withRefresh && spec.withRefresh.includes(key)) {
      collectors[key].refreshNow = () => { ops.push({ tick: spec._t, key, op: 'refreshNow' }); };
    }
    session[key] = collectors[key];
  }
  const entry = {
    session, startupReady: spec.startupReady !== false,
    routerIo: { emit: (ev, p) => emits.push({ tick: spec._t, ev, payload: p }) },
  };

  const ctx = { _COLLECTOR_DEFS: COLLECTORS, createDormancyState, payloadEmpty, io,
                console: { log() {}, error() {}, warn() {} },
                Date: { now: () => clock }, Math, Promise, setInterval };
  const api = vm.runInNewContext(
    `${slice}\n({ tick: _dormancyTick, reset: _resetDormancy, focus: _wakeForFocus, defs: _DORMANCY_DEFS });`,
    ctx, { filename: 'index.js#dormancy' });

  const steps = spec.steps.map((s, i) => {
    spec._t = i;
    clock = s.now;
    for (const [key, p] of Object.entries(s.payloads || {})) collectors[key].lastPayload = p;
    if (s.watching !== undefined) spec.watching = s.watching;
    if (s.op === 'reset') api.reset(session, entry);
    else if (s.op === 'focus') api.focus(session, entry, s.key);
    else api.tick(entry);
    return { ...s, opsAfter: ops.filter((o) => o.tick === i).map(({ tick, ...r }) => r),
             emitsAfter: emits.filter((e) => e.tick === i).map(({ tick, ...r }) => r) };
  });
  return { steps, eligible: api.defs.map((d) => d.key) };
}

// A payload shaped the way a collector's lastPayload is. `netwatch`'s emptyKey is
// `hosts`; `vlans`' is `vlans`. Chosen because both are single-key and eligible.
const P = (ts, rows, available) => {
  const p = { ts, hosts: rows };
  if (available !== undefined) p.available = available;
  return p;
};

const ENABLED = {};
for (const c of COLLECTORS) ENABLED[c.key] = true;

const CASES = [
  {
    why: 'three empty ticks put a collector to sleep, and only then is there an emit',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true,
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, []) } },
        { op: 'tick', now: 16000, payloads: { netwatch: P(2, []) } },
        { op: 'tick', now: 31000, payloads: { netwatch: P(3, []) } },
      ],
    }),
  },
  {
    // THE WATCHING GUARD. A suspended collector emits nothing, so an idle
    // session would read as universally empty and sleep the whole set for a
    // reason that has nothing to do with the router.
    why: 'nothing is judged while nobody is watching the router',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: false,
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, []) } },
        { op: 'tick', now: 16000, payloads: { netwatch: P(2, []) } },
        { op: 'tick', now: 31000, payloads: { netwatch: P(3, []) } },
        // AND THEN THREE WATCHED ONES. The first version stopped at one watched
        // tick and could not tell the guard from a supervisor that never acts:
        // the three unwatched ticks left the state untouched, so the watched one
        // was only the FIRST empty and nothing was due to happen anyway.
        { op: 'tick', now: 46000, watching: true, payloads: { netwatch: P(4, []) } },
        { op: 'tick', now: 61000, payloads: { netwatch: P(5, []) } },
        { op: 'tick', now: 76000, payloads: { netwatch: P(6, []) } },
      ],
    }),
  },
  {
    why: 'a collector the operator disabled is skipped entirely',
    ...run({
      keys: ['netwatch'], enabled: { ...ENABLED, netwatch: false }, watching: true,
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, []) } },
        { op: 'tick', now: 16000, payloads: { netwatch: P(2, []) } },
        { op: 'tick', now: 31000, payloads: { netwatch: P(3, []) } },
      ],
    }),
  },
  {
    // `available: false` is UNSUPPORTED: asleep at once, at the maximum delay.
    why: 'an unsupported menu sleeps on the first tick',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true,
      steps: [{ op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false) } }],
    }),
  },
  {
    why: 'a row appearing wakes it, and the wake is a resume plus an emit',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true,
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, []) } },
        { op: 'tick', now: 16000, payloads: { netwatch: P(2, []) } },
        { op: 'tick', now: 31000, payloads: { netwatch: P(3, []) } },
        { op: 'tick', now: 46000, payloads: { netwatch: P(4, [{ a: 1 }]) } },
      ],
    }),
  },
  {
    // THE PROBE, and which shape of collector gets which treatment.
    // `_probeCollector` prefers probe(); without one it resumes AND refreshes.
    why: 'a due probe calls probe() where one exists',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true, withProbe: ['netwatch'],
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false) } },
        { op: 'tick', now: 300000, payloads: { netwatch: P(1, [], false) } },
        { op: 'tick', now: 700000, payloads: { netwatch: P(1, [], false) } },
        // A TICK AFTER THE PROBE. Without one, removing `markProbed` survives:
        // the probe still happens at the right moment and nothing observes that
        // the hold-off was never set. Here `wakeAt` is long past, so an
        // unmarked state would probe AGAIN and a marked one waits for its
        // deadline.
        { op: 'tick', now: 710000, payloads: { netwatch: P(1, [], false) } },
      ],
    }),
  },
  {
    why: 'a due probe resumes and refreshes where there is no probe()',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true, withRefresh: ['netwatch'],
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false) } },
        { op: 'tick', now: 700000, payloads: { netwatch: P(1, [], false) } },
      ],
    }),
  },
  {
    why: 'reset wakes everything that was asleep and emits once',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true, withProbe: ['netwatch'],
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false) } },
        { op: 'reset', now: 2000 },
        { op: 'tick', now: 3000, payloads: { netwatch: P(2, []) } },
      ],
    }),
  },
  {
    // RESET WITH A MIXED SET. The case above has one collector and it is asleep,
    // so `if (st.dormant)` and `if (true)` behave identically and dropping the
    // condition SURVIVED. Here `vlans` is awake and must NOT be probed.
    why: 'reset probes only what was asleep, not every collector it knows',
    ...run({
      keys: ['netwatch', 'vlans'], enabled: ENABLED, watching: true,
      withProbe: ['netwatch', 'vlans'],
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false), vlans: P(1, [{ a: 1 }]) } },
        { op: 'reset', now: 2000 },
      ],
    }),
  },
  {
    // OPENING THE PAGE pre-empts the backoff entirely.
    why: 'focus on a dormant collector resets it, probes, and emits',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true, withProbe: ['netwatch'],
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false) } },
        { op: 'focus', now: 2000, key: 'netwatch' },
      ],
    }),
  },
  {
    why: 'focus on a collector that is NOT dormant does nothing at all',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true, withProbe: ['netwatch'],
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [{ a: 1 }]) } },
        { op: 'focus', now: 2000, key: 'netwatch' },
      ],
    }),
  },
  {
    // TWO COLLECTORS, so the emit's `dormant` list is more than one name and the
    // per-collector independence is visible.
    why: 'two collectors sleep independently and the emit lists both',
    ...run({
      keys: ['netwatch', 'vlans'], enabled: ENABLED, watching: true,
      steps: [
        { op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false), vlans: P(1, []) } },
        { op: 'tick', now: 16000, payloads: { vlans: P(2, []) } },
        { op: 'tick', now: 31000, payloads: { vlans: P(3, []) } },
      ],
    }),
  },
  {
    why: 'a collector with no payload yet is neither judged nor probed',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true,
      steps: [{ op: 'tick', now: 1000 }, { op: 'tick', now: 16000 }],
    }),
  },
  {
    why: 'startupReady false suppresses the whole tick',
    ...run({
      keys: ['netwatch'], enabled: ENABLED, watching: true, startupReady: false,
      steps: [{ op: 'tick', now: 1000, payloads: { netwatch: P(1, [], false) } }],
    }),
  },
];

// ---- Believability ---------------------------------------------------------
const byWhy = Object.fromEntries(CASES.map((c) => [c.why, c]));
const need = (k) => {
  if (!byWhy[k]) throw new Error(`a believability check names a case that is gone: ${k}`);
  return byWhy[k];
};
const allOps = CASES.flatMap((c) => c.steps.flatMap((s) => s.opsAfter.map((o) => o.op)));
const allEmits = CASES.flatMap((c) => c.steps.flatMap((s) => s.emitsAfter));

// EVERY OPERATION THE SUPERVISOR CAN PERFORM must appear, or the corpus agrees
// with a port that never performs it.
for (const op of ['suspend', 'resume', 'probe', 'refreshNow']) {
  if (!allOps.includes(op)) throw new Error(`no case ever performs ${op}`);
}
if (!allEmits.length) throw new Error('nothing is ever emitted');
if (!allEmits.every((e) => e.ev === 'collection:status')) {
  throw new Error('something other than collection:status was emitted');
}

// THE THRESHOLD, and that the emit comes with it and not before.
{
  const s = need('three empty ticks put a collector to sleep, and only then is there an emit').steps;
  if (s[0].opsAfter.length || s[1].opsAfter.length) throw new Error('it slept before the third tick');
  if (s[0].emitsAfter.length || s[1].emitsAfter.length) throw new Error('it emitted before sleeping');
  if (!s[2].opsAfter.some((o) => o.op === 'suspend')) throw new Error('the third tick did not suspend');
  if (s[2].emitsAfter.length !== 1) throw new Error('sleeping did not emit exactly once');
  if (!s[2].emitsAfter[0].payload.dormant.includes('netwatch')) {
    throw new Error('the emit does not name the sleeping collector');
  }
}
// THE WATCHING GUARD really suppresses, and the collector still sleeps once
// somebody looks — otherwise the case proves only that nothing happened.
{
  const s = need('nothing is judged while nobody is watching the router').steps;
  for (let i = 0; i < 3; i++) {
    if (s[i].opsAfter.length || s[i].emitsAfter.length) {
      throw new Error(`tick ${i} acted while nobody was watching`);
    }
  }
  // The three unwatched ticks left the STATE untouched, so the watched run has to
  // reach the threshold on its own — which is the proof that the guard skipped
  // rather than merely delayed.
  if (s[3].opsAfter.length || s[4].opsAfter.length) {
    throw new Error('a watched tick acted too early: the unwatched ticks were counted after all');
  }
  if (!s[5].opsAfter.some((o) => o.op === 'suspend')) {
    throw new Error('three WATCHED empty ticks did not sleep it, so this case cannot tell the '
      + 'guard from a supervisor that never acts');
  }
}
// THE DISABLED COLLECTOR, contrasted against the identical enabled sequence.
{
  const off = need('a collector the operator disabled is skipped entirely').steps;
  if (off.some((s) => s.opsAfter.length || s.emitsAfter.length)) {
    throw new Error('a disabled collector was acted on');
  }
}
// THE TWO PROBE SHAPES are actually different, or `_probeCollector`'s preference
// is not pinned.
{
  const withProbe = need('a due probe calls probe() where one exists').steps
    .flatMap((s) => s.opsAfter.map((o) => o.op));
  const withRefresh = need('a due probe resumes and refreshes where there is no probe()').steps
    .flatMap((s) => s.opsAfter.map((o) => o.op));
  if (!withProbe.includes('probe')) throw new Error('probe() was not preferred');
  if (withProbe.includes('refreshNow')) throw new Error('refreshNow ran alongside probe()');
  if (!withRefresh.includes('resume') || !withRefresh.includes('refreshNow')) {
    throw new Error('the no-probe fallback did not resume AND refresh');
  }
}
// FOCUS, both ways.
if (!need('focus on a dormant collector resets it, probes, and emits')
  .steps[1].emitsAfter.length) throw new Error('focus on a dormant collector did not emit');
if (need('focus on a collector that is NOT dormant does nothing at all')
  .steps[1].opsAfter.length + need('focus on a collector that is NOT dormant does nothing at all')
  .steps[1].emitsAfter.length !== 0) {
  throw new Error('focus acted on a collector that was awake');
}
// A PAYLOAD-LESS collector is left alone entirely.
if (need('a collector with no payload yet is neither judged nor probed').steps
  .some((s) => s.opsAfter.length)) throw new Error('a collector with no payload was acted on');
// And startupReady.
if (need('startupReady false suppresses the whole tick').steps[0].opsAfter.length) {
  throw new Error('the tick ran before startup was ready');
}

// THE HOLD-OFF AFTER A PROBE. Added after `markProbed`'s removal survived.
{
  const s2 = need('a due probe calls probe() where one exists').steps;
  const probes = s2.filter((x) => x.opsAfter.some((o) => o.op === 'probe'));
  if (probes.length !== 1) {
    throw new Error(`the probe case fires ${probes.length} probes; it must fire exactly one, `
      + 'with a later tick that fires NONE — otherwise removing markProbed is invisible');
  }
  if (s2[s2.length - 1].opsAfter.length !== 0) {
    throw new Error('the tick after the probe acted; the hold-off is not being exercised');
  }
}
// RESET IS SELECTIVE. Added after `if (st.dormant)` -> `if (true)` survived.
{
  const s2 = need('reset probes only what was asleep, not every collector it knows').steps;
  const reset = s2[s2.length - 1];
  const probed = reset.opsAfter.filter((o) => o.op === 'probe').map((o) => o.key);
  if (probed.length !== 1 || probed[0] !== 'netwatch') {
    throw new Error(`reset probed ${JSON.stringify(probed)}; only the dormant netwatch should be `
      + 'probed, and vlans must be left alone or this case cannot tell the condition from `true`');
  }
}

const eligible = CASES[0].eligible;
if (eligible.length < 10) throw new Error(`_DORMANCY_DEFS holds ${eligible.length} collectors`);

const json = JSON.stringify(
  { generated_from: 'src/index.js the Collector dormancy region', eligible,
    cases: CASES.map(({ eligible: _e, ...c }) => c) }, null, 2) + '\n';
if (process.argv.includes('--check')) {
  const have = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (have !== json) {
    console.error('STALE: testdata/dormancy-tick-cases.json - re-run tools/dormancy-tick-cases.js');
    process.exit(1);
  }
  console.log(`dormancy-tick-cases: up to date (${CASES.length} sequences)`);
} else {
  fs.writeFileSync(OUT, json);
  console.log(`wrote ${OUT} (${CASES.length} sequences, `
    + `${CASES.reduce((n, c) => n + c.steps.length, 0)} ticks)`);
}
